//! Checksums of known dumps, from MAME `leapster.cpp` (ROM_START) and
//! `hash/leapster.xml` (CC0-1.0; cartridges in known_carts.rs, generated by
//! scripts/gen-known-carts.py). Only names and hashes are stored: no image data.

/// Which hardware an image belongs to. `Leapster` is the supported target;
/// the others run experimentally.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Hardware {
    /// The original 2003 Leapster (all regional BaseROM revisions).
    Leapster,
    /// EXPERIMENTAL: emulated with its TV video chip and controller link.
    LeapsterTv,
    /// EXPERIMENTAL: runs on the original's model; the TV video chip can be
    /// driven for its dual screen (TV picture + handheld LCD).
    LeapsterLmax,
    /// EXPERIMENTAL: 16 MB RAM, internal SPI flash, power-controller status.
    Leapster2,
    /// LeapFrog Zippity (2009 TV console): a GeneralPlus GPL32300A (ARM9),
    /// booting from NAND flash; its games are FAT16 images with a KERNEL.BIN.
    /// Unrelated to the Leapster's hardware (MAME: `generalplus_gpl32612.cpp`).
    Zippity,
    /// LeapFrog RockIt Twist (2019 handheld, model 6060): an ARM9 GeneralPlus
    /// system-on-chip (part UNKNOWN), firmware from VTech. NOT EMULATED: a
    /// research preview (crates/ribbit-twist, docs/rockit-twist.md).
    RockItTwist,
    /// The original LeapFrog LeapPad (1999 book-and-pen pad): an 8051 base
    /// and a book cartridge; no screen (crates/ribbit-leappad).
    LeapPad,
    /// LeapFrog Didj (2008 handheld): an LF1000 (ARM926EJ-S) running Linux,
    /// its NAND built from its firmware packages (crates/ribbit-didj).
    Didj,
    /// LeapFrog Leapster Explorer (2010): the Didj's LF1000 with 64 MB, its
    /// NAND built from its firmware packages (ribbit_didj::explorer).
    Explorer,
    /// LeapFrog LeapPad Explorer (2011, the first LeapPad tablet): the
    /// Explorer's LF1000 with a 480x272 screen and its storage on an SD
    /// card, built from its firmware packages (ribbit_didj::leappad).
    LeapPadExplorer,
    /// LeapFrog LeapPad 2 (2012): an LF2000 (Nexell NXP3200, ARMv7) tablet,
    /// 480x272; Enhanced (new) only, its programs on the HLE from its
    /// firmware packages (ribbit_didj::hle::leappad2, docs/leappad2.md).
    LeapPad2,
    /// LeapFrog ClickStart: My First Computer (2007 TV console with keyboard
    /// and mouse): a Sunplus SPG28x (16-bit unSP), an 8 MB system ROM and
    /// 4 MB ROM cartridges (crates/ribbit-clickstart). EXPERIMENTAL.
    ClickStart,
    /// LeapFrog iQuest (2002-2004 handheld with a keyboard): the LeapPad's
    /// 8051 chip, a 90 x 64 LCD, flash for the user's data and 8 MB data
    /// cartridges (crates/ribbit-iquest). EXPERIMENTAL.
    IQuest,
    /// LeapFrog Turbo Twist Extreme (2004 handheld with a twist handle): the
    /// iQuest's chip, a 96 x 32 LCD and an EEPROM (crates/ribbit-iquest).
    /// EXPERIMENTAL.
    TurboTwist,
}

impl Hardware {
    /// The product name, as players know it.
    pub fn name(self) -> &'static str {
        match self {
            Hardware::Leapster => "Leapster",
            Hardware::LeapsterTv => "Leapster TV",
            Hardware::LeapsterLmax => "Leapster L-MAX",
            Hardware::Leapster2 => "Leapster 2",
            Hardware::Zippity => "Zippity",
            Hardware::RockItTwist => "RockIt Twist",
            Hardware::LeapPad => "LeapPad",
            Hardware::Didj => "Didj",
            Hardware::Explorer => "Leapster Explorer",
            Hardware::LeapPadExplorer => "LeapPad Explorer",
            Hardware::LeapPad2 => "LeapPad 2",
            Hardware::ClickStart => "ClickStart",
            Hardware::IQuest => "iQuest",
            Hardware::TurboTwist => "Turbo Twist Extreme",
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct KnownImage {
    pub name: &'static str,
    pub hardware: Hardware,
    pub size: usize,
    pub crc32: u32,
    pub sha1: &'static str,
    /// MAME flags this dump as BAD_DUMP.
    pub bad_dump: bool,
}

pub(crate) const fn fw(
    name: &'static str,
    hardware: Hardware,
    size: usize,
    crc32: u32,
    sha1: &'static str,
    bad_dump: bool,
) -> KnownImage {
    KnownImage { name, hardware, size, crc32, sha1, bad_dump }
}

